package nz.tate.bankstanding;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(BankStandingConfig.GROUP)
public interface BankStandingConfig extends Config
{
	String GROUP = "bankstanding";
	/** How much smaller "Compact overlays" draws them. */
	double COMPACT_SCALE = 0.7;

	/** Where the peek timer sits: a side of the bank, above the chatbox or beside the minimap. */
	enum PeekTimerPosition
	{
		ABOVE("Above the bank"),
		BELOW("Below the bank"),
		LEFT("Left of the bank"),
		RIGHT("Right of the bank"),
		ABOVE_CHAT("Above the chatbox"),
		BY_MINIMAP("Beside the minimap");

		private final String label;

		PeekTimerPosition(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigItem(
		keyName = "showSkillTile",
		name = "Show skill tile",
		description = "Show the skills-tab style tile with your level. The skill guide also opens from the side panel."
	)
	default boolean showSkillTile()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showCape",
		name = "Show 99 cape",
		description = "At level 99, wear the Bank Standing cape while you bank stand. Only you can see it."
	)
	default boolean showCape()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showRug",
		name = "Show rug",
		description = "From level 10, stand on a rug while you bank stand. Only you can see it."
	)
	default boolean showRug()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showSeat",
		name = "Show seat",
		description = "From level 60, sit while you bank stand. Only you can see it."
	)
	default boolean showSeat()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPet",
		name = "Show pets",
		description = "Once you have a Bank Standing pet, it keeps you company while you bank stand. Only you can see it."
	)
	default boolean showPet()
	{
		return true;
	}

	@ConfigItem(
		keyName = "fidgets",
		name = "Fidget",
		description = "From level 25, your character fidgets now and then while you bank stand."
	)
	default boolean fidgets()
	{
		return true;
	}

	@ConfigItem(
		keyName = "bankerChat",
		name = "Bankers talk",
		description = "From level 30, nearby bankers say something now and then while you bank stand."
	)
	default boolean bankerChat()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showModifiers",
		name = "Show active modifiers",
		description = "While you bank stand, show a small box for each emote or full set that's helping, with a timer for emotes. Hidden ones only show once you've found them."
	)
	default boolean showModifiers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "teaDelivery",
		name = "Bankers bring tea",
		description = "From level 85, a banker brings you a cup of tea now and then while you bank stand."
	)
	default boolean teaDelivery()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showHitsplats",
		name = "Show hitsplats",
		description = "Show a hitsplat over your character for each Bank Standing XP drop."
	)
	default boolean showHitsplats()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showXpDrops",
		name = "Show XP drops",
		description = "Show Bank Standing XP drops in the corner of the screen."
	)
	default boolean showXpDrops()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showCollectionPopups",
		name = "Show collection log popups",
		description = "Show a popup when something new goes in the collection log. It's still added to the log when this is off."
	)
	default boolean showCollectionPopups()
	{
		return true;
	}

	@ConfigItem(
		keyName = "chatMessages",
		name = "Chat messages",
		description = "Say in chat when you level up or find something new for the collection log."
	)
	default boolean chatMessages()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPeekTimer",
		name = "Show peek timer",
		description = "While you peek in the bank, show a stopwatch counting down until your stand ends."
	)
	default boolean showPeekTimer()
	{
		return true;
	}

	@ConfigItem(
		keyName = "peekTimerPosition",
		name = "Peek timer position",
		description = "Where the peek timer sits: a side of the bank, above the chatbox, or beside the minimap."
	)
	default PeekTimerPosition peekTimerPosition()
	{
		return PeekTimerPosition.ABOVE;
	}

	@ConfigItem(
		keyName = "compactOverlays",
		name = "Compact overlays",
		description = "Draw the skill tile, active modifiers, XP drops and peek timer smaller."
	)
	default boolean compactOverlays()
	{
		return false;
	}
}

