package nz.tate.bankstanding.core;

/** A named bank: a centre tile and how far from it still counts as that bank. */
public final class BankArea
{
	private final String key;
	private final String name;
	private final int x;
	private final int y;
	private final int radius;

	BankArea(String key, String name, int x, int y, int radius)
	{
		this.key = key;
		this.name = name;
		this.x = x;
		this.y = y;
		this.radius = radius;
	}

	public String getKey()
	{
		return key;
	}

	public String getName()
	{
		return name;
	}

	boolean contains(int px, int py)
	{
		return Math.abs(px - x) <= radius && Math.abs(py - y) <= radius;
	}

	int distanceTo(int px, int py)
	{
		return Math.max(Math.abs(px - x), Math.abs(py - y));
	}
}

