/** Idle time and XP earned at one bank. */
public final class BankRecord
{
	public long ticks;
	public long xp;

	/** Where the player first stood here, so an unnamed bank can still be identified. */
	public int x;
	public int y;

	/** Stands started here, counted from 1.4. */
	public int visits;
	/** When you first stood here, in epoch millis; 0 for banks first stood at before 1.4. */
	public long firstAt;

	public double hours()
	{
		return ticks * 0.6 / 3600;
	}
}

