/**
 * The collection log: rare cosmetic drops that can come with any XP roll, and the banks you've
 * stood at. Drops are flavour only; they never change XP.
 */
public final class CollectionLog
{
	/** Which entry of the log a drop is listed under. */
	public enum Group
	{
		RARE("Rare drops"),
		OUTFIT("Banker's outfit"),
		JUNK("Pocket junk"),
		ARCHIVE("Archive junk"),
		SEASONAL("Seasonal"),
		PET("Pets");

		public final String title;

		Group(String title)
		{
			this.title = title;
		}
	}

	/** One thing to collect. Rates are one in {@code rate} XP rolls. */
	public static final class Drop
	{
		public final String key;
		public final String name;
		/** The item whose icon it uses. */
		public final int icon;
		public final int rate;
		/** Whether the icon is shown turned gold. */
		public final boolean gold;
		public final boolean pet;
		public final Group group;
		/** The holiday it only drops during, or null. */
		public final Holiday holiday;
		/** Never rolled: earned by doing something, and shown as a secret until then. */
		public final boolean hidden;
		/** The banks it only drops at, or empty for anywhere. */
		public final Set<String> banks;

		Drop(String key, String name, int icon, int rate, boolean gold, boolean pet)
		{
			this(key, name, icon, rate, gold, pet ? Group.PET : Group.RARE, null);
		}

		Drop(String key, String name, int icon, int rate, boolean gold, Group group, Holiday holiday)
		{
			this(key, name, icon, rate, gold, group, holiday, false);
		}

		Drop(String key, String name, int icon, int rate, boolean gold, Group group, Holiday holiday, boolean hidden)
		{
			this.key = key;
			this.name = name;
			this.icon = icon;
			this.rate = rate;
			this.gold = gold;
			this.pet = group == Group.PET;
			this.group = group;
			this.holiday = holiday;
			this.hidden = hidden;
			this.banks = Collections.emptySet();
		}

		/** Pocket junk that only drops at these banks. */
		Drop(String key, String name, int icon, int rate, String... banks)
		{
			this.key = key;
			this.name = name;
			this.icon = icon;
			this.rate = rate;
			this.gold = false;
			this.pet = false;
			this.group = Group.ARCHIVE;
			this.holiday = null;
			this.hidden = false;
			this.banks = new HashSet<>(Arrays.asList(banks));
		}

		public boolean rare()
		{
			return group == Group.RARE || group == Group.OUTFIT || group == Group.PET;
		}
	}

	private static final int SEASONAL_RATE = 2_000;
	private static final String ARCHIVE_WEST = "fractured-archive-west";
