	));

	/** Rarest first, which is the order drops are rolled in. Hidden drops are left out. */
	private static final List<Drop> BY_RARITY;

	static
	{
		List<Drop> sorted = new ArrayList<>();
		for (Drop drop : DROPS)
		{
			if (!drop.hidden)
			{
				sorted.add(drop);
			}
		}
		sorted.sort((a, b) -> Integer.compare(b.rate, a.rate));
		BY_RARITY = Collections.unmodifiableList(sorted);
	}

	/** What's saved for each drop you've had. */
	public static final class Obtained
	{
		public int count;
		/** When the first one dropped, in epoch milliseconds. */
		public long firstAt;
		/** How many rolls it took to get the first one. */
		public long firstRolls;
	}

	private CollectionLog()
	{
	}

	/**
	 * Rolls for a drop alongside one XP roll; the rarest is checked first and at most one
	 * drops. Seasonal drops only roll on their holiday, and a bank's own junk only at that bank.
	 */
	public static Drop roll(Random random, LocalDate today, String bankKey)
	{
		for (Drop drop : BY_RARITY)
		{
			if ((drop.holiday == null || drop.holiday.isOn(today))
				&& (drop.banks.isEmpty() || drop.banks.contains(bankKey)) && random.nextInt(drop.rate) == 0)
			{
				return drop;
			}
		}
		return null;
	}

	public static Drop find(String key)
	{
		for (Drop drop : DROPS)
		{
			if (drop.key.equals(key))
			{
				return drop;
			}
		}
		return null;
	}

	/** Adds a drop to the log; true if it's the first one. */
	public static boolean collect(Progress progress, Drop drop, long now)
	{
		Obtained obtained = progress.collection.get(drop.key);
		boolean first = obtained == null;
		if (first)
		{
			obtained = new Obtained();
			obtained.firstAt = now;
			obtained.firstRolls = progress.rolls;
			progress.collection.put(drop.key, obtained);
		}
		obtained.count++;
		return first;
	}

	/** Whether the moneybag, the pet that hops round you, has dropped. */
	public static boolean hasPet(Progress progress)
	{
		return progress.collection.containsKey(MONEYBAG);
	}

	/** Whether the bank rat, the pet that scurries round you, has dropped. */
	public static boolean hasRat(Progress progress)
	{
		return progress.collection.containsKey(RAT);
	}

	/** Whether this pet comes out while you stand: you have it, and haven't put it away in the log. */
	public static boolean petOut(Progress progress, String key)
	{
		return progress.collection.containsKey(key) && !progress.hiddenPets.contains(key);
	}

	/** How many of the banks listed in the log you've stood at. */
	public static int banksVisited(Progress progress)
	{
		int visited = 0;
		for (String region : BankRegions.names())
		{
			for (String key : BankRegions.keys(region))
			{
				if (progress.banks.containsKey(key))
				{
					visited++;
				}
			}
		}
		return visited;
	}
}

