		}
		named.removeAll(seen);
		assertEquals(Collections.singleton("tutorial-island"), named);
		assertNull(BankRegions.regionOf("tutorial-island"));
		assertEquals("Misthalin", BankRegions.regionOf("varrock-west"));
	}
}

