	@Test
	public void clanCloakAndVexillumAtTheClanHall()
	{
		assertEquals(1, Modifiers.evaluate(at("clan-hall", 25716, 25725)).bonusHit);
		assertEquals(0, Modifiers.evaluate(at("clan-hall", 25716)).bonusHit);
