	@Test
	public void jesterAtJatizso()
	{
		assertEquals(1, Modifiers.evaluate(at("jatizso", 10836, 10837, 10838, 10839, 10840)).bonusHit);
	}

	@Test
	public void fullInventoryOfFishAtTheFishingGuild()
	{
		StandContext c = at("fishing-guild", 4151);
