	@Test
	public void newSpotFadesOverTenHours()
	{
		assertEquals(Modifiers.MEDIUM, Modifiers.newSpot(0), EPS);
		assertEquals(Modifiers.MEDIUM / 2, Modifiers.newSpot(5), EPS);
		assertEquals(0, Modifiers.newSpot(10), EPS);
