package nz.tate.bankstanding.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class StandTrackerTest
{
	private final StandTracker tracker = new StandTracker();

	private int stand(int ticks)
	{
		int rolls = 0;
		for (int i = 0; i < ticks; i++)
		{
			if (tracker.tick(3185, 3436, 0, true, false))
			{
				rolls++;
			}
		}
		return rolls;
	}

	@Test
	public void firstDropComesAfterThirtySecondsThenEveryInterval()
	{
		int interval = XpRoller.ROLL_INTERVAL_TICKS;
		assertEquals(0, stand(StandTracker.START_DELAY_TICKS));
		assertFalse(tracker.isStanding());
		assertEquals(0, stand(interval - 1));
		assertTrue(tracker.isStanding());
		assertEquals(1, stand(1));
		assertEquals(10, stand(interval * 10));
	}

	@Test
	public void idleAtBankFromTheFirstStillTick()
	{
		assertFalse(tracker.isIdleAtBank());
		stand(1);
		assertTrue(tracker.isIdleAtBank());
		assertFalse(tracker.isStanding());
		tracker.tick(3186, 3436, 0, true, false);
		assertFalse(tracker.isIdleAtBank());
		tracker.tick(3186, 3436, 0, false, false);
		assertFalse(tracker.isIdleAtBank());
	}

	@Test
	public void walkingRestartsTheDelay()
	{
		stand(60);
		assertFalse(tracker.tick(3186, 3436, 0, true, false));
		assertFalse(tracker.isStanding());
		assertEquals(0, stand(StandTracker.START_DELAY_TICKS));
	}

	@Test
	public void usingTheBankRestartsTheDelay()
	{
		stand(60);
		tracker.tick(3185, 3436, 0, true, true);
		assertFalse(tracker.isStanding());
	}

	@Test
	public void quickPeekPausesTheStand()
	{
		tracker.setUnlocks(StandTracker.START_DELAY_TICKS, Unlocks.PEEK_TICKS);
		stand(60);
		for (int i = 0; i < Unlocks.PEEK_TICKS; i++)
		{
			assertFalse(tracker.tick(3185, 3436, 0, true, true));
			assertTrue(tracker.isStanding());
		}
		stand(1);
		assertTrue(tracker.isStanding());

		for (int i = 0; i <= Unlocks.PEEK_TICKS; i++)
		{
			tracker.tick(3185, 3436, 0, true, true);
		}
		assertFalse(tracker.isStanding());
	}

	@Test
	public void quickPeekCountsDownUntilTheStandEnds()
	{
		tracker.setUnlocks(StandTracker.START_DELAY_TICKS, Unlocks.PEEK_TICKS);
		stand(60);
		assertEquals(0, tracker.peekTicksLeft());
		for (int i = Unlocks.PEEK_TICKS; i >= 1; i--)
		{
			tracker.tick(3185, 3436, 0, true, true);
			assertEquals(i, tracker.peekTicksLeft());
		}
		tracker.tick(3185, 3436, 0, true, true);
		assertEquals(0, tracker.peekTicksLeft());
	}

	@Test
	public void noPeekLimitAt99()
	{
		tracker.setUnlocks(StandTracker.START_DELAY_TICKS, Unlocks.NO_PEEK_LIMIT);
		stand(60);
		for (int i = 0; i < 10_000; i++)
		{
			tracker.tick(3185, 3436, 0, true, true);
		}
		assertTrue(tracker.isStanding());
		assertEquals(0, tracker.peekTicksLeft());
	}

	@Test
	public void noCountdownWithoutQuickPeek()
	{
		stand(60);
		tracker.tick(3185, 3436, 0, true, true);
		assertEquals(0, tracker.peekTicksLeft());
	}

	@Test
	public void higherLevelsStartSooner()
	{
		tracker.setUnlocks(Unlocks.startDelayTicks(99), 0);
		assertEquals(0, stand(Unlocks.startDelayTicks(99)));
		assertTrue(stand(XpRoller.ROLL_INTERVAL_TICKS) == 1);
	}

	@Test
	public void leavingRangeRestartsTheDelay()
	{
		stand(60);
		tracker.tick(3185, 3436, 0, false, false);
		assertFalse(tracker.isStanding());
	}

	@Test
	public void realXpRestartsTheDelay()
	{
		stand(60);
		tracker.realXpGained();
		assertFalse(tracker.isStanding());
		assertEquals(0, stand(StandTracker.START_DELAY_TICKS));
	}

	@Test
	public void theFirstPositionAfterResetIsNotMovement()
	{
		stand(10);
		tracker.reset();
		assertFalse(tracker.tick(3000, 3000, 0, true, false));
		for (int i = 1; i < StandTracker.START_DELAY_TICKS + 4; i++)
		{
			tracker.tick(3000, 3000, 0, true, false);
		}
		assertTrue(tracker.isStanding());
	}
}

